const radarUi={tab:'issues',data:null,q:'',topic:'',status:'',platform:'',period:72,limit:10,loading:false};
const rDate=v=>v?new Date(v).toLocaleString('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'})+' WIB':'Belum tersedia';
const rNum=v=>v===null||v===undefined?'—':Number(v).toLocaleString('id-ID');
const rStatus={new:'Baru',saved:'Referensi',ignored:'Diabaikan',discussed:'Sudah dibahas'};
const rVerify={unchecked:'Belum diperiksa',verified:'Terverifikasi',compare:'Perlu pembanding'};
const rPost=(path,body,method='POST')=>api('/api/radar/'+path,{method,body:JSON.stringify(body)});
const rLens=ids=>(radarUi.data?.lenses||[]).filter(l=>ids.includes(l.id)).map(l=>`<span class="radar-lens radar-${l.id}">${esc(l.name)}</span>`).join('');
function radarRating(stats){const rating=Math.max(1,Math.min(5,stats.rating||1)),score=stats.score||0;return `<span class="radar-rating" aria-label="Rating ${rating} dari 5, skor ${score} dari 100"><span aria-hidden="true">${'★'.repeat(rating)}${'☆'.repeat(5-rating)}</span><strong>${rating}/5</strong><small>${score}/100</small></span>`;}
function radarVisibleIssues(data,tab,{q='',topic='',status='',platform=''}={}){
 const pool=tab==='references'?data.issues.filter(i=>['saved','discussed'].includes(i.status)):data.issues.filter(i=>i.stats.relevant!==false&&!['ignored','discussed'].includes(i.status));
 const search=q.trim().toLowerCase();
 return pool.filter(i=>(tab!=='issues'||!status||i.status===status)&&(!topic||i.topicIds.includes(topic))&&(!platform||i.sources.some(s=>s.platform===platform))&&
  [i.title,...i.sources.flatMap(source=>[source.title,source.publisher,source.excerpt||''])].join(' ').toLowerCase().includes(search))
  .toSorted((a,b)=>b.stats.score-a.stats.score||Date.parse(b.stats.latestPublishedAt||0)-Date.parse(a.stats.latestPublishedAt||0)||a.id.localeCompare(b.id));
}
function radarPage(data,tab,options={},now=Date.now()){
 const all=radarVisibleIssues(data,tab,options),hours=Number(options.period||72);
 const recent=tab==='issues'?all.filter(i=>{const time=Date.parse(i.stats.latestPublishedAt||''),age=now-time;return Number.isFinite(time)&&age>=0&&age<hours*3600000;}):all;
 const fallback=tab==='issues'&&recent.length===0&&all.length>0,pool=fallback?all:recent;
 return {items:pool.slice(0,options.limit||10),total:pool.length,fallback};
}
function radarTrend(stats){const trend=stats.trend||{state:'unavailable'},labels={rising:'↑ Naik',falling:'↓ Menurun',stable:'→ Stabil',unavailable:'Belum ada pembanding'};return `<span class="radar-trend radar-trend-${Object.hasOwn(labels,trend.state)?trend.state:'unavailable'}">${labels[trend.state]||labels.unavailable}</span>`;}
function radarFreshness(stats){return stats.freshness==='older'?'Berita lama':stats.freshness==='undated'?'Tanggal belum tersedia':stats.limitedCoverage?'Liputan terbatas':'Liputan terpantau';}
function radarAngles(issue){return `<details class="radar-method"><summary>Sudut riset untuk konten Reframe</summary><p>Pertanyaan riset untuk <strong>${esc(issue.title)}</strong>; belum merupakan kesimpulan fakta.</p><div class="radar-angle-grid"><div><strong>Sejarah & data</strong><p>Kapan masalah mulai muncul? Cari kronologi, arsip, dan data yang dapat diperiksa.</p></div><div><strong>Struktur sistem</strong><p>Aturan dan insentif apa yang berperan? Siapa diuntungkan dan siapa menanggung biaya?</p></div><div><strong>Dampak manusia</strong><p>Bagaimana dampaknya pada kehidupan sehari-hari? Perspektif siapa yang belum terdengar?</p></div></div><p class="hint">Alur: bukti sejarah/data → bedah sistem → empati manusia. Periksa sumber sebelum menulis script.</p></details>`;}
function radarMethodology(data){const method=data.methodology||{},weights=method.weights||{coverage:40,activity:30,recency:20,breadth:10};return `<details class="radar-method"><summary>Cara pengelompokan & peringkat Radar</summary><p>Judul atau cuplikan isi yang serupa dikelompokkan bila peristiwa dan waktunya berdekatan. Perbedaan lokasi, tahun, angka kebijakan, atau keputusan dijaga agar tidak tercampur. Cuplikan RSS bukan artikel penuh.</p><p>10 isu dengan skor tertinggi tampil lebih dulu, tanpa batas minimal bintang. Pilih periode 24 jam, 3 hari, atau 7 hari; bila tidak ada liputan pada periode tersebut, bahan lama ditampilkan dengan penanda. Gunakan Lihat lainnya untuk membuka peringkat berikutnya.</p><div class="radar-method-weights">${[['coverage','Sebaran penerbit'],['activity','Aktivitas 24 jam'],['recency','Kebaruan'],['breadth','Lintas platform']].map(([id,label])=>`<span>${label} <strong>${weights[id]} poin</strong></span>`).join('')}</div><p class="hint">Rating berdasarkan liputan terpantau, bukan kebenaran atau jaminan viral. Repost dan berita tanpa tanggal tidak menaikkan skor. Arah tren membandingkan jumlah penerbit aktif / 24 jam dengan pengamatan sebelumnya, minimal berjarak 30 menit.</p></details>`;}
const rDialog=document.createElement('dialog');rDialog.className='radar-dialog';rDialog.id='radarDialog';document.body.append(rDialog);
function radarModal(title,html){clearInterval(radarUi.aiTimer);radarUi.aiTimer=null;rDialog.classList.toggle('radar-writing',/AI|Rangkuman|Ringkasan|pengelompokan/.test(title));rDialog.innerHTML=`<div class="radar-modal-head"><h2>${esc(title)}</h2><button type="button" class="icon-button" data-r-close aria-label="Tutup">✕</button></div><div class="radar-modal-body">${html}<div id="radarModalError" class="notice hide" role="alert"></div></div>`;if(!rDialog.open)rDialog.showModal();rDialog.querySelector('[data-r-close]').onclick=()=>rDialog.close();}
async function radarRun(fn){try{return await fn()}catch(e){const box=rDialog.open?$('#radarModalError'):$('#radarError');if(box){box.textContent=e.message;box.classList.remove('hide')}else toast(e.message);return null}}
window.renderRadar=body=>{if(body.querySelector('#radarPanel'))return;body.innerHTML=`<section id="radarPanel"><div class="radar-hero"><div><span class="eyebrow">EDITORIAL RADAR</span><h2>Pilih isu teratas untuk konten.</h2><p>Berita dan video serupa dalam satu kelompok. Rangkuman data, klaim faktual dan opini tanpa kuota AI.</p></div><div class="feature-actions"><button class="btn" id="radarDaily">Ringkasan harian</button><button class="btn" id="radarWeekly">Ringkasan mingguan</button><button class="btn" id="radarSettings">Topik & Sumber</button><button class="btn primary" id="radarSync">Sinkronkan</button></div></div><div id="radarError" class="notice hide" role="alert"></div><div class="radar-tabs" role="tablist">${[['issues','Radar Teratas'],['channels','Pantauan Channel'],['references','Referensi']].map(([id,title])=>`<button role="tab" data-r-tab="${id}" aria-selected="${id===radarUi.tab}">${title}</button>`).join('')}</div><div class="radar-tools"><input id="radarSearch" aria-label="Cari Radar" placeholder="Cari isu atau channel…"><select id="radarTopic" aria-label="Filter topik"><option value="">Semua topik</option></select><select id="radarStatus" aria-label="Filter status"><option value="">Semua status</option>${Object.entries(rStatus).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><select id="radarPlatform" aria-label="Filter platform"><option value="">Semua sumber</option><option value="YouTube">Video YouTube</option><option value="Berita / Web">Artikel / berita</option></select><select id="radarPeriod" aria-label="Periode liputan"><option value="24">24 jam</option><option value="72" selected>3 hari</option><option value="168">7 hari</option></select><button class="btn" id="radarAdd">+ Link referensi</button></div><div id="radarCoverage"></div><div id="radarMethodology"></div><div id="radarList"><div class="hub-panel empty">Memuat Radar…</div></div><div id="radarFooter" class="hint"></div></section>`;$('#radarSearch').value=radarUi.q;$('#radarSearch').oninput=e=>{radarUi.q=e.target.value;radarUi.limit=10;radarList()};$('#radarTopic').onchange=e=>{radarUi.topic=e.target.value;radarUi.limit=10;radarList()};$('#radarStatus').value=radarUi.status;$('#radarStatus').onchange=e=>{radarUi.status=e.target.value;radarUi.limit=10;radarList()};$('#radarPlatform').value=radarUi.platform;$('#radarPlatform').onchange=e=>{radarUi.platform=e.target.value;radarUi.limit=10;radarList()};$('#radarPeriod').value=radarUi.period;$('#radarPeriod').onchange=e=>{radarUi.period=Number(e.target.value);radarUi.limit=10;radarList()};$('#radarAdd').onclick=()=>radarSource();$('#radarDaily').onclick=()=>radarRun(()=>radarDigest('daily'));$('#radarWeekly').onclick=()=>radarRun(()=>radarDigest('weekly'));$('#radarSettings').onclick=()=>radarSettings();$('#radarSync').onclick=()=>radarRun(async()=>{if(radarUi.loading)return;radarUi.loading=true;$('#radarSync').disabled=true;$('#radarSync').textContent='Menyinkronkan…';try{const result=await rPost('sync',{});await radarLoad();toast(`${result.news} link berita · ${result.videos} video diperiksa${result.errors.length?' · Ada sumber belum tersinkron':''}`)}finally{radarUi.loading=false;if($('#radarSync')){$('#radarSync').disabled=false;$('#radarSync').textContent='Sinkronkan'}}});body.querySelector('.radar-tabs').onclick=e=>{const b=e.target.closest('[data-r-tab]');if(!b)return;radarUi.tab=b.dataset.rTab;radarUi.limit=10;body.querySelectorAll('[data-r-tab]').forEach(x=>x.setAttribute('aria-selected',x===b));radarList()};$('#radarList').onclick=e=>radarRun(async()=>{const b=e.target.closest('[data-r-issue],[data-r-channel-add],[data-r-channel-ai],[data-r-video],[data-r-more]');if(!b)return;if(b.hasAttribute('data-r-more')){radarUi.limit+=10;return radarList()}if(b.dataset.rIssue)return radarIssue(b.dataset.rIssue);if(b.hasAttribute('data-r-channel-add'))return radarChannel();if(b.dataset.rChannelAi)return radarAI('analysis',{channelId:b.dataset.rChannelAi,script:''});if(b.dataset.rVideo){const [channelId,id]=b.dataset.rVideo.split(':');const c=radarUi.data.channels.find(c=>c.id===channelId),v=c.videos.find(v=>v.id===id);return radarSource(null,{url:v.url,title:v.title,publisher:c.name,publishedAt:v.publishedAt});}});if(!radarUi.refreshTimer)radarUi.refreshTimer=setInterval(()=>{if(document.visibilityState==='visible'&&!rDialog.open&&!radarUi.loading&&$('#radarPanel')&&$('#radarPanel').offsetParent!==null)radarLoad().catch(()=>{});},5*60*1000);radarRun(()=>radarLoad());};
function radarAIPath(){return '/api/radar'+(radarUi.aiProvider?'?aiProvider='+encodeURIComponent(radarUi.aiProvider):'');}
function radarVideoMetadata(video){return `<div class="radar-video">${/^https:\/\/i\.ytimg\.com\//.test(video.thumbnail)?'<img src="'+esc(video.thumbnail)+'" alt="Thumbnail video" loading="lazy">':''}<span class="hint">${rNum(video.viewCount)} views · ${esc(video.duration||'Durasi belum tersedia')}</span></div>`;}
function radarGroupingReport(report){
 const bases={title_exact:'Judul sama setelah normalisasi',title_similarity:'Kemiripan judul',content_similarity:'Kemiripan cuplikan isi',multiple_sources:'Dukungan beberapa sumber dalam kelompok',anchor:'Sumber awal / belum ada pembanding',manual_rule:'Materi berulang mengikuti koreksi penggabungan manual'};
 const modes={anchor:'Sumber awal',automatic:'Masuk otomatis',manual_rule:'Mengikuti aturan penggabungan manual',manual_add:'Ditambahkan ke kelompok secara manual',needs_review:'Perlu tinjau: cocok ke kelompok yang sudah dipisahkan'};
 const percent=score=>Math.round(Math.max(0,Math.min(1,Number(score)||0))*100);
 const sourceName=id=>report.sources.find(s=>s.id===id)?.title||'Sumber referensi tersimpan';
 return `<p class="hint">${esc(report.note)}</p><div class="radar-grouping-status"><span class="radar-chip">Engine v${report.methodVersion} · Tanpa AI</span>${report.locked?'<span class="radar-chip">Koreksi editorial dilindungi</span>':''}${report.separationRule?'<span class="radar-chip">Aturan pemisahan tersimpan</span>':''}</div>${report.reviewRequired?'<div class="notice">Sumber baru cocok dengan beberapa kelompok yang pernah dipisahkan. Periksa sumber lalu gunakan Gabungkan / Pisahkan, atau tandai kelompok sudah diperiksa.</div>':''}<ol class="radar-grouping-list">${report.sources.map(source=>{const match=source.evaluation,old=source.provenance;return `<li><h3>${/^https?:\/\//i.test(source.url)?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>`:esc(source.title)}</h3><p class="hint">${esc(source.publisher)} · ${esc(source.platform)} · ${esc(rDate(source.publishedAt))}</p><details><summary>Riwayat masuk sumber</summary>${old?`<p>${esc(modes[old.mode]||old.mode)} · ${esc(rDate(old.at))} · engine v${old.methodVersion}${old.basis?' · '+esc(bases[old.basis]||old.basis):''}${old.mode==='automatic'?' · kemiripan '+percent(old.score)+'%':''}</p>`:'<p class="hint">Riwayat masuk belum tersimpan untuk sumber lama.</p>'}</details><div class="radar-grouping-evaluation"><strong>${match.matched?esc(bases[match.basis]||'Cocok dengan kelompok')+' · '+percent(match.score)+'%':match.basis==='anchor'?'Belum ada pembanding':'Perlu pembanding / koreksi manual'}</strong><p class="hint">Evaluasi saat ini${Number.isFinite(match.windowHours)?' · rentang publikasi/penemuan '+Number(match.windowHours).toFixed(1)+' jam':''}. Kemiripan teks bukan probabilitas kebenaran.</p>${match.sharedTerms.length?'<p><small>Kata bersama: '+match.sharedTerms.map(esc).join(' · ')+'</small></p>':''}${match.sharedEntities.length?'<p><small>Penanda bersama: '+match.sharedEntities.map(e=>esc(e.value)).join(' · ')+'</small></p>':''}${match.referenceSourceIds.length?'<p class="hint">Pembanding: '+match.referenceSourceIds.map(id=>esc(sourceName(id))).join('; ')+'</p>':''}${match.reasons.map(reason=>'<p class="hint">'+esc(reason)+'</p>').join('')}</div></li>`;}).join('')}</ol>${report.history.length?'<details class="radar-method"><summary>Riwayat koreksi kelompok ('+report.history.length+')</summary>'+report.history.toReversed().map(h=>'<p>'+esc({split:'Pemisahan manual',merge:'Penggabungan manual',reviewed:'Kelompok ditandai sudah diperiksa'}[h.action]||h.action)+' · '+esc(rDate(h.at))+'</p>').join('')+'</details>':''}`;
}
async function radarGroupingIssue(id){
 const epoch=radarUi.groupingEpoch=(radarUi.groupingEpoch||0)+1;
 radarModal('Alasan pengelompokan','<p id="radarGroupingLoading" class="hint">Memeriksa kecocokan sumber…</p>');rDialog.onclick=null;
 const loading=$('#radarGroupingLoading'),report=await api('/api/radar/issues/'+id+'/grouping');
 if(epoch!==radarUi.groupingEpoch||!rDialog.open||!loading.isConnected)return;
 radarModal('Alasan pengelompokan',`<h3>${esc(report.title)}</h3>${radarGroupingReport(report)}<div class="radar-issue-actions">${report.reviewRequired?'<button class="btn primary" id="radarGroupingReviewed">Tandai kelompok sudah diperiksa</button>':''}<button class="btn" id="radarGroupingBack">Kembali ke isu</button></div>`);
 $('#radarGroupingBack').onclick=()=>radarIssue(id);
 if($('#radarGroupingReviewed'))$('#radarGroupingReviewed').onclick=()=>radarRun(async()=>{const button=$('#radarGroupingReviewed');button.disabled=true;try{await rPost('issues/'+id,{revision:report.revision,groupingReview:false},'PATCH');await radarLoad();if(epoch===radarUi.groupingEpoch&&rDialog.open&&button.isConnected)await radarGroupingIssue(id);toast('Kelompok ditandai sudah diperiksa. Ini tidak memverifikasi kebenaran sumber.');}finally{if(button.isConnected)button.disabled=false;}});
}
function radarEngineReport(report){
 const link=number=>{const source=report.sources.find(s=>s.number===number);return source?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer" title="${esc(source.publisher+' · '+source.title)}">[${number}]</a>`:'';};
 const item=entry=>`<p>${esc(entry.text)} <span class="radar-engine-cites">${entry.sourceNumbers.map(link).join(' ')}</span></p>${entry.status?`<small class="hint">${entry.headlineOnly?'Judul saja · ':''}${entry.attributed?'Pernyataan narasumber · ':''}${entry.publishers||0} penerbit memuat kalimat ini${entry.sourceVerified?' · Ada sumber ditandai terverifikasi':''}</small>`:''}`;
 return `<section class="radar-engine-report"><span class="radar-engine-badge">Engine · Tanpa AI · 0 kuota AI</span><p class="hint">Kategori mengikuti pola bahasa sumber; klaim faktual tetap perlu diperiksa.</p>${report.quality?`<div class="radar-engine-quality" aria-label="Cakupan bahan rangkuman"><span><strong>${report.quality.excerptSources}</strong> sumber dengan cuplikan</span><span><strong>${report.quality.headlineOnlySources}</strong> sumber judul saja</span>${report.quality.truncatedSources?`<span class="radar-engine-warning"><strong>${report.quality.truncatedSources}</strong> cuplikan terpotong</span>`:''}${report.quality.emptySources?`<span class="radar-engine-warning"><strong>${report.quality.emptySources}</strong> sumber belum cukup bahan</span>`:''}</div>`:''}<div class="radar-engine-lead">${report.summary.map(item).join('')||'<p>Belum ada kalimat yang dapat diekstrak.</p>'}</div><div class="radar-engine-grid">${[['data','Data & angka'],['facts','Klaim faktual'],['opinions','Opini / dugaan']].map(([key,label])=>`<section><h3>${label} <small>${report[key].length} / ${report.totals[key]}</small></h3>${report[key].map(item).join('')||'<p class="hint">Belum terdeteksi pada bahan yang tersedia.</p>'}</section>`).join('')}</div>${report.conflicts.length?`<div class="notice"><strong>Angka perlu dibandingkan</strong>${report.conflicts.map(c=>item(c.left)+item(c.right)+'<p class="hint">'+esc(c.note)+'</p>').join('')}</div>`:''}<details class="radar-method"><summary>Kronologi, aktor, angka & kebutuhan riset</summary><p class="hint">${esc(report.chronologyNote||'')}</p>${(report.chronology||[]).map(c=>'<p>'+esc(rDate(c.at))+' · '+item(c)+'</p>').join('')}<h3>Nama di sumber</h3>${(report.actors||[]).map(c=>'<strong>'+esc(c.name)+'</strong>'+item(c)).join('')||'<p class="hint">Belum ditemukan nama dengan pola eksplisit.</p>'}<h3>Angka penting</h3>${(report.importantNumbers||[]).map(c=>'<strong>'+esc(c.value)+'</strong>'+item(c)).join('')} ${(report.differences||[]).map(c=>'<div class="notice">'+item(c.left)+item(c.right)+'<p>'+esc(c.note)+'</p></div>').join('')}<h3>Kebutuhan riset</h3>${(report.researchGaps||[]).map(g=>'<p>'+esc(g)+'</p>').join('')}</details><details class="radar-method"><summary>Sumber (${report.sourceCount}) & batasan engine</summary><p>${esc(report.note)}</p>${report.limitations.map(l=>'<p>'+esc(l)+'</p>').join('')}<ol>${report.sources.map(s=>`<li>${link(s.number)} ${esc(s.publisher)} · ${esc(s.title)}<br><small>${esc(s.platform)} · ${esc(rDate(s.publishedAt))}</small></li>`).join('')}</ol></details></section>`;
}
async function radarEngineIssue(id){
 const epoch=radarUi.engineEpoch=(radarUi.engineEpoch||0)+1;
 radarModal('Rangkuman tanpa AI','<p id="radarEngineLoading" class="hint">Menyusun data, klaim faktual dan opini…</p>');
 const loading=$('#radarEngineLoading'),report=await api('/api/radar/issues/'+id+'/summary');
 if(epoch!==radarUi.engineEpoch||!rDialog.open||!loading.isConnected)return;
 radarModal('Rangkuman tanpa AI',`<h3>${esc(report.title)}</h3>${radarEngineReport(report)}<div class="radar-issue-actions"><button class="btn primary" id="radarEngineCopy">Salin rangkuman</button><button class="btn" id="radarEngineBack">Kembali ke isu</button></div>`);
 $('#radarEngineBack').onclick=()=>radarIssue(id);
 $('#radarEngineCopy').onclick=()=>radarRun(async()=>{await navigator.clipboard.writeText(report.text);toast('Rangkuman dan rujukan disalin.');});
}
async function radarDigest(period='daily',date){
  const epoch=radarUi.digestEpoch=(radarUi.digestEpoch||0)+1;
  radarModal('Ringkasan Radar','<p class="hint" id="radarDigestLoading">Memuat ringkasan…</p>');
  const loading=$('#radarDigestLoading');
  const params=new URLSearchParams({period,topic:radarUi.topic||'',...(date?{date}:{})});
  const report=await api('/api/radar/digest?'+params);
  if(epoch!==radarUi.digestEpoch||!rDialog.open||!loading.isConnected)return;
  radarModal('Ringkasan Radar',`<div class="radar-two"><label>Periode<select id="radarDigestPeriod"><option value="daily"${period==='daily'?' selected':''}>Harian</option><option value="weekly"${period==='weekly'?' selected':''}>Mingguan (Senin–Minggu)</option></select></label><label>Tanggal acuan (WIB)<input type="date" id="radarDigestDate" value="${esc(report.date)}"></label></div><p class="hint">${esc(rDate(report.startAt))} → ${esc(rDate(report.throughAt))}${report.partial?' · Periode masih berjalan':''}${radarUi.topic?' · Mengikuti filter topik':''}</p><div class="radar-digest-stats"><span><strong>${report.groups}</strong> kelompok isu</span><span><strong>${report.sourceCount}</strong> sumber</span><span><strong>${report.platforms.YouTube||0}</strong> video YouTube</span><span><strong>${report.publishers}</strong> penerbit / akun</span></div><span class="radar-engine-badge">Engine · Tanpa AI · 0 kuota AI</span>${report.summary?'<p class="radar-engine-overview">'+esc(report.summary)+'</p>':''}<p class="hint">${esc(report.note)}</p>${report.items.length?'<button class="btn" id="radarDigestAI">Analisis lanjut dengan AI (opsional)</button>':'<div class="empty">Belum ada liputan bertanggal dalam periode ini. Pilih tanggal lain atau Sinkronkan Radar.</div>'}<ol class="radar-digest-list">${report.items.map(i=>`<li><button class="btn" data-digest-issue="${i.id}">${esc(i.title)}</button>${radarRating(i.stats)}${i.groupingReview?'<p class="notice">Pengelompokan perlu ditinjau.</p>':''}<p class="hint">${i.sources.length} sumber · ${esc(rStatus[i.status])} · ${Object.entries(i.stats.counts).map(([p,n])=>esc(p)+' '+n).join(' · ')}</p>${i.report?`<div class="radar-engine-preview">${i.report.summary.map(x=>'<p>'+esc(x.text)+' ['+x.sourceNumbers.join(', ')+']</p>').join('')}</div><details class="radar-method"><summary>Data, klaim faktual & opini — tanpa AI</summary>${radarEngineReport(i.report)}</details>`:`<p class="radar-excerpt">${esc(i.sources.find(s=>s.excerpt)?.excerpt?.slice(0,500)||'Judul saja; buka sumber untuk konteks lengkap.')}</p>`}${i.sources.slice(0,3).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.publisher)} · ${esc(s.title)} ↗</a>`).join('<br>')}</li>`).join('')}</ol>${report.groups>10?'<p class="hint">10 kelompok teratas ditampilkan; jumlah total mencakup seluruh kelompok pada periode ini.</p>':''}`);
  const reload=()=>radarRun(()=>radarDigest($('#radarDigestPeriod').value,$('#radarDigestDate').value));
  $('#radarDigestPeriod').onchange=reload;$('#radarDigestDate').onchange=reload;
  if($('#radarDigestAI'))$('#radarDigestAI').onclick=()=>radarRun(()=>radarAI('digest',{script:'',digestPeriod:period,digestDate:report.date,digestTopic:report.topic}));
  rDialog.querySelectorAll('[data-digest-issue]').forEach(b=>b.onclick=()=>radarIssue(b.dataset.digestIssue));
}
async function radarLoad(){const result=await api(radarAIPath());radarUi.data=result;if(!$('#radarPanel'))return;const selected=radarUi.topic;$('#radarTopic').innerHTML='<option value="">Semua topik</option>'+result.topics.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}${t.enabled?'':' (nonaktif)'}</option>`).join('');$('#radarTopic').value=selected;radarList();}
function radarList(){const r=radarUi.data,list=$('#radarList');if(!r||!list)return;$('#radarPlatform').classList.toggle('hide',radarUi.tab==='channels');$('#radarTopic').classList.toggle('hide',radarUi.tab==='channels');$('#radarStatus').classList.toggle('hide',radarUi.tab!=='issues');$('#radarPeriod').classList.toggle('hide',radarUi.tab!=='issues');$('#radarAdd').textContent=radarUi.tab==='channels'?'+ Channel':'+ Link referensi';$('#radarAdd').onclick=()=>radarUi.tab==='channels'?radarChannel():radarSource();$('#radarMethodology').innerHTML=radarUi.tab==='issues'?radarMethodology(r):'';$('#radarCoverage').innerHTML=`<div class="radar-coverage">${Object.entries(r.coverage).map(([name,state])=>`<span><b>${esc(name)}</b> ${esc(state)}</span>`).join('')}</div>`;$('#radarFooter').innerHTML=`Terdeteksi dari sumber yang dipantau · Link ≠ konfirmasi independen.<br>Pembaruan terakhir: ${esc(rDate(r.sync.lastCompletedAt))}. Rating dihitung ${esc(rDate(r.radarSummary?.ratedAt))}. Otomatis sekitar setiap 1 jam, maksimal 3 topik berita dan 1 pencarian topik YouTube bergiliran per jam.${r.sync.youtubeRetryAt&&Date.parse(r.sync.youtubeRetryAt)>Date.now()?'<br>YouTube dibatasi sampai '+esc(rDate(r.sync.youtubeRetryAt)):''}${r.sync.errors?.length?'<details><summary>Masalah sinkronisasi ('+r.sync.errors.length+')</summary>'+r.sync.errors.map(e=>'<p>'+esc(e.source)+': '+esc(e.message)+'</p>').join('')+'</details>':''}<div class="radar-ai-footer">${radarAIConnection(r.ai,radarUi.aiModel||r.ai.model)}<button class="btn mini" id="radarAISettings">Koneksi & model AI</button></div>`;$('#radarAISettings').onclick=()=>radarRun(()=>radarAI(null,{}));const q=radarUi.q.toLowerCase();if(radarUi.tab==='channels'){const channels=r.channels.filter(c=>(c.name||c.url).toLowerCase().includes(q));list.innerHTML=`<div class="radar-channel-grid">${channels.map(c=>`<article class="hub-panel radar-channel"><div class="radar-channel-head"><div><h3>${esc(c.name||c.url)}</h3><span class="radar-chip">${esc({inspiration:'Inspirasi',competitor:'Pembanding',reference:'Referensi'}[c.role])}</span></div><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer" class="btn mini">Channel ↗</a></div><p class="hint">Snapshot ${esc(rDate(c.lastSyncAt))} · Metrik publik, maksimum 10 video terbaru.</p><button class="btn mini" data-r-channel-ai="${c.id}">Analisis AI</button>${c.videos.map(v=>`<div class="radar-video">${/^https:\/\/i\.ytimg\.com\//.test(v.thumbnail)?`<img src="${esc(v.thumbnail)}" alt="" loading="lazy">`:''}<div><a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${esc(v.title)}</a><div class="hint">${esc(rDate(v.publishedAt))} · ${esc(v.duration)}</div><div class="radar-video-stats">${rNum(v.viewCount)} views · ${rNum(v.likeCount)} likes · ${rNum(v.commentCount)} komentar</div><div class="hint">${v.delta?`Δ views ${rNum(v.delta.viewCount)} sejak ${esc(rDate(v.previousAt))}`:'Belum ada snapshot pembanding; pertumbuhan belum tersedia.'}</div><button class="btn mini" data-r-video="${c.id}:${v.id}">Simpan sebagai referensi</button></div></div>`).join('')||'<div class="empty">Klik Sinkronkan untuk mengambil video publik channel.</div>'}</article>`).join('')}</div>${!channels.length?'<div class="hub-panel empty"><h3>Pantau channel pilihan Anda.</h3><p>Tambahkan URL /@handle atau /channel/UC… untuk merekam video dan snapshot publik.</p><button class="btn primary" data-r-channel-add>+ Channel</button></div>':''}`;return;}const page=radarPage(r,radarUi.tab,{q:radarUi.q,topic:radarUi.topic,status:radarUi.status,platform:radarUi.platform,period:radarUi.period,limit:radarUi.limit}),issues=page.items;list.innerHTML=issues.length?`<p class="hint radar-ranking-summary" role="status">Menampilkan ${issues.length} dari ${page.total} kelompok · urutan skor tertinggi${page.fallback?' · Tidak ada liputan dalam periode pilihan; menampilkan bahan lama atau tanpa tanggal.':''}</p><div class="radar-grid">${issues.map((i,index)=>`<button class="radar-card" data-r-issue="${i.id}"><div class="radar-card-top"><span class="radar-priority radar-${i.stats.priority}">${radarUi.tab==='issues'?'#'+(index+1)+' · Radar teratas':'Referensi'}</span><span class="radar-chip">${rStatus[i.status]}</span></div>${radarRating(i.stats)}<div class="radar-card-signals">${radarTrend(i.stats)}<span class="radar-chip">${esc(radarFreshness(i.stats))}</span></div><h3>${esc(i.title)}</h3>${i.groupingReview?'<span class="radar-chip radar-grouping-review">Pengelompokan perlu ditinjau</span>':''}<div class="radar-lenses">${rLens(i.lenses)}</div><div class="radar-counts"><strong>${i.stats.sources}<small>artikel / sumber</small></strong><strong>${i.stats.platforms}<small>platform</small></strong><strong>${i.stats.publishers}<small>penerbit / akun</small></strong></div><div class="radar-platforms">${Object.entries(i.stats.counts).map(([p,n])=>`<span>${esc(p)} ${n}</span>`).join('')}</div><p class="hint">${i.stats.publishers24h} penerbit aktif / 24 jam · ${i.stats.new24h} liputan baru</p><p class="hint">${esc(i.stats.reason)}</p><div class="radar-card-bottom">Publikasi terbaru: ${esc(rDate(i.stats.latestPublishedAt))}${i.contentIds.length?' · '+i.contentIds.length+' konten':''}</div></button>`).join('')}</div>${page.total>issues.length?'<button class="btn radar-more" data-r-more>Lihat 10 lainnya</button>':''}`:`<div class="hub-panel empty"><h3>${radarUi.tab==='issues'?'Belum ada bahan Radar yang sesuai.':'Belum ada referensi yang sesuai.'}</h3><p>${radarUi.tab==='issues'?'Sinkronkan atau sesuaikan topik dan filter. Semua rating dapat tampil; hasil tetap harus sesuai topik aktif. Bahan lain tersedia melalui Topik & Sumber → Kelola bahan pantauan.':'Simpan isu atau link pilihan sebagai referensi.'}</p></div>`;}
function radarSettings(){const r=radarUi.data;if(!r)return;radarModal('Topik & Sumber',`<p class="hint">Tiga lensa bisa dilebur dalam satu konten. Perubahan hanya tersimpan setelah menekan Simpan.</p><div class="radar-lenses">${rLens(['history','system','human'])}</div><h3>Bahan pantauan</h3><p class="hint">${r.radarSummary?.ranked||0} kelompok sesuai topik aktif dari ${r.issues.length} kelompok tersimpan. Radar mengurutkan semua rating, dengan 10 kartu pertama.</p><button class="btn" data-r-review>Kelola bahan pantauan</button><h3>Topik pantauan</h3><button class="btn primary" data-r-new-topic>+ Topik custom</button>${r.topics.map(t=>`<div class="radar-setting-row"><div><strong>${esc(t.name)}</strong><p class="hint">${esc(t.keywords.join(', '))}</p><span class="radar-chip">${t.enabled?'Aktif':'Nonaktif'}</span></div><button class="btn mini" data-r-edit-topic="${t.id}">Edit</button></div>`).join('')}<h3>RSS custom</h3><p class="hint">RSS dicocokkan dengan keyword topik aktif. Google News tersedia otomatis untuk topik Berita / RSS.</p><button class="btn" data-r-feed>+ RSS</button>${r.feeds.map(f=>`<div class="radar-setting-row"><div><strong>${esc(f.name)}</strong><p class="hint">${esc(f.url)}</p></div><button class="btn mini danger" data-r-remove="feeds:${f.id}">Hapus</button></div>`).join('')}<h3>Channel dipantau</h3>${r.channels.map(c=>`<div class="radar-setting-row"><strong>${esc(c.name||c.url)}</strong><button class="btn mini danger" data-r-remove="channels:${c.id}">Hapus</button></div>`).join('')||'<p class="hint">Belum ada channel.</p>'}`);rDialog.onclick=e=>radarRun(async()=>{const b=e.target.closest('[data-r-close],[data-r-new-topic],[data-r-edit-topic],[data-r-feed],[data-r-remove],[data-r-review]');if(!b)return;if(b.hasAttribute('data-r-close'))return rDialog.close();if(b.hasAttribute('data-r-new-topic'))return radarTopic();if(b.dataset.rEditTopic)return radarTopic(r.topics.find(t=>t.id===b.dataset.rEditTopic));if(b.hasAttribute('data-r-review'))return radarReview();if(b.hasAttribute('data-r-feed'))return radarFeed();if(b.dataset.rRemove){if(!confirm('Hapus sumber pemantauan? Referensi yang sudah tersimpan tetap tersedia.'))return;const [kind,id]=b.dataset.rRemove.split(':'),item=r[kind].find(x=>x.id===id);await rPost(kind+'/'+id,{revision:item.revision},'DELETE');await radarLoad();radarSettings();}});}
function radarReview(){const issues=radarUi.data.issues.toSorted((a,b)=>b.stats.score-a.stats.score);radarModal('Kelola bahan pantauan',`<p class="hint">Pilih satu kelompok untuk memeriksa sumber, menyimpan sebagai referensi, menggabungkan, atau menghapusnya. Radar menampilkan peringkat teratas; semua bahan tetap bisa dikelola di sini.</p><form id="radarReviewForm" class="radar-form"><label>Kelompok isu<select id="radarReviewIssue" required><option value="">Pilih isu…</option>${issues.map(i=>`<option value="${esc(i.id)}">${i.stats.rating}/5 · ${esc(i.title)} · ${i.stats.sources} link</option>`).join('')}</select></label><button class="btn primary" type="submit"${issues.length?'':' disabled'}>Buka detail</button></form>`);rDialog.onclick=null;$('#radarReviewForm').onsubmit=e=>{e.preventDefault();radarIssue($('#radarReviewIssue').value);};}
function radarForm(title,html,submit){radarModal(title,`<form id="radarForm" class="radar-form">${html}<div class="radar-form-bottom"><span class="hint">Belum tersimpan sampai Anda menekan Simpan.</span><button class="btn primary" type="submit">Simpan</button></div></form>`);rDialog.onclick=null;$('#radarForm').onsubmit=e=>{e.preventDefault();radarRun(async()=>{const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{await submit(f);await radarLoad();rDialog.close();toast('Tersimpan.')}finally{b.disabled=false}})};}
function radarTopic(t={name:'',keywords:[],exclusions:[],lenses:['system'],sources:['news','youtube'],language:'id',region:'ID',enabled:true}){radarForm(t.id?'Edit topik':'Topik custom',`<label>Nama topik<input name="name" required maxlength="100" value="${esc(t.name)}"></label><label>Keyword (pisahkan koma)<textarea name="keywords" required rows="3">${esc(t.keywords.join(', '))}</textarea></label><label>Keyword pengecualian<input name="exclusions" value="${esc(t.exclusions.join(', '))}"></label><fieldset><legend>Lensa editorial</legend>${radarUi.data.lenses.map(l=>`<label><input type="checkbox" name="lenses" value="${l.id}"${t.lenses.includes(l.id)?' checked':''}> ${esc(l.name)}</label>`).join('')}</fieldset><fieldset><legend>Sumber pemantauan</legend>${[['news','Berita / RSS'],['youtube','YouTube (keyword topik + channel pantauan)']].map(([v,n])=>`<label><input type="checkbox" name="sources" value="${v}"${t.sources.includes(v)?' checked':''}> ${n}</label>`).join('')}</fieldset><div class="radar-two"><label>Bahasa (2 huruf)<input name="language" required pattern="[a-z]{2}" value="${esc(t.language)}"></label><label>Wilayah (2 huruf besar)<input name="region" required pattern="[A-Z]{2}" value="${esc(t.region)}"></label></div><label><input name="enabled" type="checkbox"${t.enabled?' checked':''}> Aktif</label>${t.id?'<button class="btn mini danger" type="button" id="radarDeleteTopic">Hapus topik</button>':''}`,async f=>{const split=name=>f.elements[name].value.split(',').map(x=>x.trim()).filter(Boolean),checks=name=>[...f.querySelectorAll(`[name="${name}"]:checked`)].map(x=>x.value);await rPost('topics'+(t.id?'/'+t.id:''),{name:f.elements.name.value,keywords:split('keywords'),exclusions:split('exclusions'),lenses:checks('lenses'),sources:checks('sources'),language:f.elements.language.value,region:f.elements.region.value,enabled:f.elements.enabled.checked,revision:t.revision},t.id?'PATCH':'POST');});if(t.id)$('#radarDeleteTopic').onclick=()=>radarRun(async()=>{if(!confirm('Hapus topik ini? Isu dan sumber tetap tersedia.'))return;await rPost('topics/'+t.id,{revision:t.revision},'DELETE');await radarLoad();radarSettings()});}
function radarFeed(){radarForm('Tambah RSS',`<label>Nama sumber<input name="name" required maxlength="100"></label><label>URL RSS<input name="url" type="url" required maxlength="2048" placeholder="https://…/feed"></label>`,f=>rPost('feeds',{name:f.elements.name.value,url:f.elements.url.value,enabled:true}));}
function radarChannel(){radarForm('Pantau channel YouTube',`<label>URL channel<input name="url" type="url" required maxlength="2048" placeholder="https://www.youtube.com/@handle"></label><label>Peran<select name="role"><option value="inspiration">Inspirasi</option><option value="competitor">Pembanding</option><option value="reference">Referensi</option></select></label><p class="hint">Data publik diperbarui melalui Sinkronkan. Tidak membaca Analytics pribadi channel lain.</p>`,f=>rPost('channels',{url:f.elements.url.value,role:f.elements.role.value}));}
function radarSource(issueId=null,fields={}){radarForm('Simpan link referensi',`<label>Judul / peristiwa<input name="title" required maxlength="300" value="${esc(fields.title||'')}"></label><label>Link sumber<input name="url" type="url" required maxlength="2048" value="${esc(fields.url||'')}"></label><label>Penerbit / akun<input name="publisher" maxlength="160" value="${esc(fields.publisher||'')}"></label><label>Tanggal publikasi (opsional)<input name="publishedAt" type="datetime-local" value="${fields.publishedAt?wibInput(fields.publishedAt):''}"></label><label>Kutipan / catatan sumber<textarea name="excerpt" maxlength="3000" rows="4"></textarea></label><label><input type="checkbox" name="repost"> Salinan / repost dari sumber lain</label>`,f=>rPost('sources',{issueId,title:f.elements.title.value,url:f.elements.url.value,publisher:f.elements.publisher.value,publishedAt:inputIso(f.elements.publishedAt.value),excerpt:f.elements.excerpt.value,coverage:'manual',repost:f.elements.repost.checked}));}
function radarIssue(id){const i=radarUi.data.issues.find(i=>i.id===id);if(!i)return;radarModal(i.title,`${radarRating(i.stats)}<div class="radar-card-signals">${radarTrend(i.stats)}<span class="radar-chip">${esc(radarFreshness(i.stats))}</span></div><div class="radar-lenses">${rLens(i.lenses)}</div><p class="hint">${esc(i.stats.reason)}</p>${i.stats.trend?.since?'<p class="hint">Perubahan penerbit aktif / 24 jam: '+(i.stats.trend.deltaPublishers24h>0?'+':'')+i.stats.trend.deltaPublishers24h+' sejak '+esc(rDate(i.stats.trend.since))+'.</p>':'<p class="hint">Tren menunggu dua pengamatan berjarak minimal 30 menit.</p>'}<details class="radar-method"><summary>Rincian skor ${i.stats.score}/100</summary><div class="radar-method-weights">${[['coverage','Sebaran penerbit'],['activity','Aktivitas 24 jam'],['recency','Kebaruan'],['breadth','Lintas platform']].map(([key,label])=>`<span>${label} <strong>${i.stats.components[key]} poin</strong></span>`).join('')}</div><p class="hint">${i.stats.undated} sumber tanpa tanggal publikasi. Repost tidak menambah skor. Ini indikator liputan, bukan validasi kebenaran.</p></details>${radarAngles(i)}<div class="radar-issue-actions"><select id="radarIssueStatus" aria-label="Status isu">${Object.entries(rStatus).map(([v,n])=>`<option value="${v}"${i.status===v?' selected':''}>${n}</option>`).join('')}</select><button class="btn" data-r-save-status>Simpan status</button><button class="btn primary" data-r-draft>Buat draft</button><button class="btn primary" data-r-engine>Rangkum tanpa AI</button><button class="btn" data-r-ai>Angle AI (opsional)</button><button class="btn" data-r-add-source>+ Sumber</button><button class="btn" data-r-edit-issue>Edit detail</button><button class="btn" data-r-grouping>Alasan pengelompokan</button><button class="btn" data-r-merge>Gabungkan isu</button>${i.sources.length>1?'<button class="btn" data-r-split>Pisahkan sumber</button>':''}<button class="btn danger" data-r-delete-issue>Hapus isu</button></div><p class="hint">Tanggal peristiwa: ${esc(rDate(i.eventDate))} · Tanggal publikasi ada pada setiap sumber.</p>${i.contentIds.length?'<h3>Konten terkait</h3>'+i.contentIds.map(id=>{const c=radarUi.data.linkedContents.find(c=>c.id===id);return c?'<button class="btn mini" data-r-content="'+id+'">'+esc(c.title)+'</button>':'<span class="hint">Konten telah dihapus</span>'}).join(''):''}${i.groupingReview?'<p class="notice">Pengelompokan perlu ditinjau karena sumber cocok ke beberapa kelompok yang sudah dipisahkan. Buka Alasan pengelompokan.</p>':''}<h3>Ringkasan bahan</h3><p class="radar-excerpt">${esc(i.sources.find(s=>s.excerpt)?.excerpt||'Belum ada cuplikan atau catatan. Gunakan Rangkum tanpa AI atau buka sumber asli untuk menambah konteks.')}</p><p class="hint">Cuplikan sumber, belum disimpulkan sebagai fakta terverifikasi.</p><h3>Sumber & kronologi (${i.sources.length} link)</h3><p class="hint">${i.stats.publishers} penerbit/akun · ${i.stats.platforms} platform. Link berbeda dapat menyadur sumber yang sama; verifikasi tetap diperlukan.</p><ol class="radar-sources">${i.sources.toSorted((a,b)=>Date.parse(a.publishedAt||a.discoveredAt)-Date.parse(b.publishedAt||b.discoveredAt)).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><div class="hint">${esc(s.platform)} · ${esc(s.publisher)}<br>Publikasi: ${esc(rDate(s.publishedAt))}<br>Ditemukan: ${esc(rDate(s.discoveredAt))} · ${s.coverage==='headline'?'Judul saja':s.coverage==='snippet'?(s.platform==='YouTube'?'Judul & deskripsi video, bukan transkrip':'Judul & cuplikan RSS, bukan artikel penuh'):'Catatan manual'}</div>${s.video?radarVideoMetadata(s.video):''}${s.excerpt?'<p class="radar-excerpt">'+esc(s.excerpt)+'</p>':''}<div class="radar-source-verify"><select data-r-verify="${s.id}" aria-label="Verifikasi sumber">${Object.entries(rVerify).map(([v,n])=>`<option value="${v}"${s.verification===v?' selected':''}>${n}</option>`).join('')}</select><label><input type="checkbox" data-r-repost="${s.id}"${s.repost?' checked':''}> Salinan / repost</label><button class="btn mini" data-r-save-source="${s.id}">Simpan</button></div></li>`).join('')}</ol>`);rDialog.onclick=e=>radarRun(async()=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-r-close'))return rDialog.close();if(b.hasAttribute('data-r-draft'))return radarDraft(i);if(b.hasAttribute('data-r-engine'))return radarEngineIssue(i.id);if(b.hasAttribute('data-r-ai'))return radarAI('summary',{issueId:i.id,script:''});if(b.hasAttribute('data-r-add-source'))return radarSource(i.id);if(b.dataset.rContent){rDialog.close();navigate('library');return openContent(b.dataset.rContent);}if(b.hasAttribute('data-r-edit-issue'))return radarEditIssue(i);if(b.hasAttribute('data-r-grouping'))return radarGroupingIssue(i.id);if(b.hasAttribute('data-r-merge'))return radarMerge(i);if(b.hasAttribute('data-r-split'))return radarSplit(i);if(b.hasAttribute('data-r-delete-issue')){if(!confirm('Hapus isu dan sumbernya?'))return;await rPost('issues/'+i.id,{revision:i.revision},'DELETE');await radarLoad();rDialog.close();return;}let patch;if(b.hasAttribute('data-r-save-status'))patch={status:$('#radarIssueStatus').value};if(b.dataset.rSaveSource){const sid=b.dataset.rSaveSource;patch={sourceId:sid,verification:rDialog.querySelector(`[data-r-verify="${sid}"]`).value,repost:rDialog.querySelector(`[data-r-repost="${sid}"]`).checked};}if(patch){b.disabled=true;try{await rPost('issues/'+i.id,{revision:i.revision,...patch},'PATCH');await radarLoad();radarIssue(i.id)}finally{b.disabled=false}}});}
function radarEditIssue(i){radarForm('Detail isu',`<label>Judul<input name="title" required maxlength="300" value="${esc(i.title)}"></label><label>Tanggal peristiwa (opsional)<input name="eventDate" type="datetime-local" value="${i.eventDate?wibInput(i.eventDate):''}"></label><fieldset><legend>Lensa editorial</legend>${radarUi.data.lenses.map(l=>`<label><input type="checkbox" name="lenses" value="${l.id}"${i.lenses.includes(l.id)?' checked':''}> ${esc(l.name)}</label>`).join('')}</fieldset>`,f=>rPost('issues/'+i.id,{revision:i.revision,title:f.elements.title.value,eventDate:inputIso(f.elements.eventDate.value),lenses:[...f.querySelectorAll('[name=lenses]:checked')].map(x=>x.value)},'PATCH'));}
function radarMerge(i){radarForm('Gabungkan sumber ke isu ini',`<p>${esc(i.title)}</p><label>Isu yang akan digabung<select name="from" required><option value="">Pilih isu</option>${radarUi.data.issues.filter(x=>x.id!==i.id).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><p class="hint">Pastikan kedua isu membahas peristiwa yang sama. Semua sumber dan hubungan konten akan dipindah ke isu tujuan.</p>`,f=>{const from=radarUi.data.issues.find(x=>x.id===f.elements.from.value);return rPost('issues/'+i.id+'/merge',{revision:i.revision,fromId:from.id,fromRevision:from.revision})});}
function radarSplit(i){
 radarModal('Pisahkan sumber menjadi isu baru',`<form id="radarSplitForm" class="radar-form"><label>Judul kelompok baru<input name="title" required maxlength="300" placeholder="Judul peristiwa yang dipisahkan"></label><fieldset><legend>Pilih sebagian sumber yang akan dipindah</legend>${i.sources.map(source=>`<label><input type="checkbox" name="sourceIds" value="${esc(source.id)}"> ${esc(source.title)} · ${esc(source.publisher)}</label>`).join('')}</fieldset><p class="hint">Sisakan minimal satu sumber pada kelompok asal. Link, tanggal dan verifikasi dipertahankan. Konten yang sudah terhubung tetap pada kelompok asal. Aturan pemisahan disimpan. Sumber baru yang cocok ke kedua kelompok akan memerlukan tinjauan; kelompok koreksi tidak digabung balik saat migrasi.</p><div class="radar-form-bottom"><span class="hint">Belum berubah sampai Anda menekan Pisahkan.</span><button class="btn primary" type="submit">Pisahkan</button></div></form>`);
 rDialog.onclick=null;$('#radarSplitForm').onsubmit=e=>{e.preventDefault();radarRun(async()=>{const f=e.currentTarget,button=f.querySelector('[type=submit]'),sourceIds=[...f.querySelectorAll('[name=sourceIds]:checked')].map(x=>x.value);if(!sourceIds.length||sourceIds.length>=i.sources.length)throw Error('Pilih sebagian sumber; sisakan minimal satu pada kelompok asal.');button.disabled=true;try{const result=await rPost('issues/'+i.id+'/split',{revision:i.revision,title:f.elements.title.value,sourceIds});await radarLoad();radarIssue(result.issueId);toast('Kelompok dipisahkan.')}finally{button.disabled=false}});};
}
function radarDraft(i,fields={}){radarModal('Pratinjau draft',`<form id="radarDraftForm" class="radar-form"><label>Judul<input name="title" required maxlength="200" value="${esc((fields.title||i.title).slice(0,200))}"></label><label>Kategori video<select name="format"><option value="long">Long</option><option value="shorts"${fields.format==='shorts'?' selected':''}>Short</option></select></label><label>Pilar produksi<select name="pillar"><option value="">Tanpa pilar</option>${hub.data.pillars.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>Angle<textarea name="angle" rows="3" maxlength="4000">${esc(fields.angle||'')}</textarea></label><fieldset><legend>Sumber yang ikut ke Riset & Aset</legend>${i.sources.map(s=>`<label><input type="checkbox" name="sources" value="${s.id}" checked> ${esc(s.title)}</label>`).join('')}</fieldset><p class="hint">Draft dibuka di editor. Belum tersimpan sampai Anda menekan Simpan.</p><button class="btn primary" type="submit">Buka draft di editor</button></form>`);rDialog.onclick=null;$('#radarDraftForm').onsubmit=e=>{e.preventDefault();radarRun(async()=>{const f=e.currentTarget,selected=[...f.querySelectorAll('[name=sources]:checked')].map(x=>x.value),sources=i.sources.filter(s=>selected.includes(s.id)).map(s=>({id:crypto.randomUUID(),label:s.title,url:s.url,notes:s.excerpt,verified:s.verification==='verified'}));const brief=['Angle: '+f.elements.angle.value,'Lensa editorial: '+radarUi.data.lenses.filter(l=>i.lenses.includes(l.id)).map(l=>l.name).join(' + '),'Alur: bukti sejarah/data → struktur sistem → empati dan refleksi manusia.'].join('\n');rDialog.close();navigate('library');await newContent({title:f.elements.title.value,format:f.elements.format.value,pillarId:f.elements.pillar.value,brief,script:fields.script||'',sources,radarIssueId:i.id});});};}
function radarAIConnection(config,model){
  const connection=config.connection||{state:config.configured?'unchecked':'unconfigured'},result=config.modelResults?.[model];
  const unavailable=connection.state==='connected'&&!config.models?.some(m=>m.id===model);
  const labels={unconfigured:'Belum dikonfigurasi',unchecked:'Koneksi belum diperiksa',checking:'Memeriksa koneksi…',connected:'API terhubung',error:'Koneksi gagal'};
  const badge=(state,label)=>`<span class="radar-ai-status radar-ai-${state}" role="status"><span aria-hidden="true">${state==='ready'||state==='connected'?'✓':state==='error'||state==='busy'||state==='unavailable'?'!':'●'}</span> ${esc(label)}</span>`;
  const state=Object.hasOwn(labels,connection.state)?connection.state:'unchecked';
  const generation=result?badge(['ready','fallback'].includes(result.state)?'ready':result.state==='busy'?'busy':'error',result.state==='fallback'?'Pratinjau: provider cadangan':result.state==='ready'?'Pratinjau terakhir berhasil':result.state==='busy'?'Pratinjau terakhir: gagal sementara':'Pratinjau terakhir gagal'):config.configured?badge('unchecked','Belum ada hasil pratinjau'):'';
  const remaining=Math.max(0,Math.ceil((Date.parse(result?.retryAt||'')-Date.now())/1000)||0),probe=config.generationTest?.model===model?config.generationTest:null;
  return `${probe?badge(probe.state,probe.state==='ready'?'Uji jawaban berhasil':'Uji jawaban gagal')+'<span class="hint">'+esc(probe.message)+' · '+esc(rDate(probe.checkedAt))+'</span>':''}${badge(state,labels[state])}${unavailable?badge('unavailable','Model tidak tersedia'):''}${generation}${connection.message?'<span class="hint">Koneksi: '+esc(connection.message)+'</span>':''}${result?'<span class="hint">Pratinjau: '+esc(result.message)+(remaining?' Ulangi dalam '+remaining+' detik.':'')+'<br>'+esc(rDate(result.checkedAt))+'</span>':''}${unavailable?'<span class="hint">Pilih model lain dari daftar yang tersedia.</span>':''}<span class="hint">${esc(config.provider||'AI')} · ${esc(model||'Model belum dipilih')}</span>`;
}
function radarAIRetry(config,model){
  const current=config.providers?.find(p=>p.providerId===config.providerId),retry=Math.max(Date.parse(config.modelResults?.[model]?.retryAt||'')||0,Date.parse(current?.quotaRetryAt||'')||0);
  if(retry<=Date.now())return 0;
  const candidates=config.autoFallback?config.providers?.filter(p=>p.configured&&p.providerId!==config.providerId)||[]:[];
  if(candidates.some(p=>!(Date.parse(p.quotaRetryAt)>Date.now())))return 0;
  const next=Math.min(retry,...candidates.map(p=>Date.parse(p.quotaRetryAt)));
  return Math.max(0,Math.ceil((next-Date.now())/1000));
}
function radarAIControls(config){
  const models=config.models||[];
  if(radarUi.aiProvider!==config.providerId){radarUi.aiModel=config.model;radarUi.aiProvider=config.providerId;}
  if(!models.some(m=>m.id===radarUi.aiModel)&&radarUi.aiModel!==config.model)radarUi.aiModel=config.model;
  const selected=radarUi.aiModel||config.model;
  return `<div class="radar-ai-panel">${config.selectionMessage?'<p class="hint">'+esc(config.selectionMessage)+'</p>':''}${config.modelSource==='default'?'<p class="hint">Model bawaan: '+esc(config.model)+'. Dapat diganti melalui pengaturan model server.</p>':''}${config.providers?`<label for="radarAIProvider">Provider utama<select id="radarAIProvider">${config.providers.map(p=>`<option value="${esc(p.providerId)}"${p.providerId===config.providerId?' selected':''}>${esc(p.providerId==='openai'?'GPT (OpenAI)':p.provider)}${p.configured?'':' — belum dikonfigurasi'}</option>`).join('')}</select></label><p class="hint">${config.autoFallback?'Pindah otomatis saat kuota habis, layanan gagal, atau timeout':'Perpindahan otomatis nonaktif'}. Cadangan: ${config.providers.filter(p=>p.configured&&p.providerId!==config.providerId).map(p=>esc(p.provider)).join(', ')||'belum ada provider lain yang dikonfigurasi'}.</p><details class="hint"><summary>Rincian provider</summary>${config.providers.map(p=>`<p><strong>${esc(p.providerId==='openai'?'GPT (OpenAI)':p.provider)}</strong> · ${esc(p.model||'Model belum tersedia')}: ${esc(!p.configured?p.setupMessage:Date.parse(p.quotaRetryAt)>Date.now()?p.availabilityMessage||'Dalam jeda':p.generationTest?.state==='ready'?'Uji jawaban berhasil':'Dikonfigurasi; kesiapan jawaban belum dipastikan')}</p>`).join('')}</details>`:''}<div id="radarAIConnection" class="radar-ai-connection">${radarAIConnection(config,selected)}</div>${config.configured?`<div class="radar-ai-options"><label for="radarAIModel">Model untuk pratinjau<select id="radarAIModel"><option value="${esc(config.model)}">${esc(config.model)} (default)${config.connection?.state==='connected'&&!models.some(m=>m.id===config.model)?' — tidak tersedia':''}</option>${models.filter(m=>m.id!==config.model).map(m=>`<option value="${esc(m.id)}">${esc(m.label)} · ${esc(m.id)}</option>`).join('')}</select></label><button class="btn" id="radarCheckAI">Cek koneksi & model</button><button class="btn" id="radarTestAI">Uji jawaban</button></div><p class="hint">Cek koneksi memeriksa daftar model. Uji jawaban memastikan model bisa membalas dan memakai kuota API provider. Hanya pratinjau berhasil dihitung ke batas harian aplikasi.</p>`:'<p class="hint">'+esc(config.setupMessage||'Isi API key dan model pada pengaturan server.')+'</p>'}${config.lastAttempts?.length?'<details class="hint"><summary>Rincian percobaan terakhir</summary>'+config.lastAttempts.map(a=>'<p>'+esc(a.provider)+' · '+esc(a.model)+': '+esc(a.message)+'</p>').join('')+'</details>':''}</div>`;
}
function radarAIBind(config){
  clearInterval(radarUi.aiTimer);radarUi.aiTimer=null;
  const provider=$('#radarAIProvider'),select=$('#radarAIModel'),check=$('#radarCheckAI');
  if(provider)provider.onchange=()=>radarRun(async()=>{
    const controls=$('#radarAIControls'),generate=$('#radarGenerateAI');provider.disabled=true;if(generate)generate.disabled=true;
    try{const next=(await api('/api/radar?aiProvider='+encodeURIComponent(provider.value))).ai;if(controls.isConnected){radarUi.aiProvider=next.providerId;radarUi.aiModel=next.model;radarUi.data.ai=next;controls.innerHTML=radarAIControls(next);radarAIBind(next);radarList();}}
    finally{if(provider.isConnected){provider.disabled=false;if(generate)generate.disabled=!config.configured;}}
  });
  if(!select){if($('#radarGenerateAI'))$('#radarGenerateAI').disabled=true;return;}
  select.value=radarUi.aiModel||config.model;
  if($('#radarAIUsage'))$('#radarAIUsage').textContent=config.used+'/'+config.limit+' permintaan hari ini';
  const update=()=>{radarUi.aiModel=select.value;$('#radarAIConnection').innerHTML=radarAIConnection(config,select.value);const b=$('#radarGenerateAI'),remaining=radarAIRetry(config,select.value);if(b){b.disabled=remaining>0||(config.connection?.state==='connected'&&!config.models?.some(m=>m.id===select.value));b.textContent=remaining?'Coba lagi ('+remaining+' dtk)':'Buat pratinjau';}if(remaining>0&&!radarUi.aiTimer)radarUi.aiTimer=setInterval(()=>{if(!select.isConnected||!rDialog.open){clearInterval(radarUi.aiTimer);radarUi.aiTimer=null;return;}update();},1000);if(!remaining&&radarUi.aiTimer){clearInterval(radarUi.aiTimer);radarUi.aiTimer=null;}};
  select.onchange=update;update();
  const probe=$('#radarTestAI');if(probe)probe.onclick=()=>radarRun(async()=>{const controls=$('#radarAIControls');probe.disabled=true;check.disabled=true;if($('#radarTestAI'))$('#radarTestAI').disabled=true;select.disabled=true;if(provider)provider.disabled=true;const generate=$('#radarGenerateAI');if(generate)generate.disabled=true;probe.textContent='Menguji jawaban…';try{const next=await rPost('ai/test',{provider:config.providerId,model:select.value});radarUi.data.ai=next;if(controls.isConnected){controls.innerHTML=radarAIControls(next);radarAIBind(next);}radarList();}finally{if(probe.isConnected){probe.disabled=false;check.disabled=false;if($('#radarTestAI'))$('#radarTestAI').disabled=false;select.disabled=false;if(provider)provider.disabled=false;probe.textContent='Uji jawaban';update();}}});
  check.onclick=()=>radarRun(async()=>{clearInterval(radarUi.aiTimer);radarUi.aiTimer=null;const controls=$('#radarAIControls');check.disabled=true;if($('#radarTestAI'))$('#radarTestAI').disabled=true;select.disabled=true;if(provider)provider.disabled=true;check.textContent='Memeriksa…';$('#radarAIConnection').innerHTML=radarAIConnection({...config,modelResults:{},connection:{state:'checking'}},select.value);const generate=$('#radarGenerateAI');if(generate)generate.disabled=true;try{const next=await rPost('ai/check',{provider:config.providerId});radarUi.data.ai=next;if(controls.isConnected){controls.innerHTML=radarAIControls(next);radarAIBind(next);}radarList();}finally{if(check.isConnected){check.disabled=false;if($('#radarTestAI'))$('#radarTestAI').disabled=false;select.disabled=false;if(provider)provider.disabled=false;check.textContent='Cek koneksi & model';update();}}});
}
async function radarAI(action,context){
  const edit=hub.editing,epoch=edit?.epoch;if(!radarUi.data)await radarLoad();
  // Refresh saved connection evidence without making a provider call.
  radarUi.data.ai=(await api(radarAIPath())).ai;
  const config=radarUi.data.ai;
  radarModal(action?'Bantuan AI':'Koneksi AI',`<div id="radarAIControls">${radarAIControls(config)}</div><p class="hint" id="radarAIUsage">${config.used}/${config.limit} permintaan hari ini</p>${action?'<p>Hasil AI adalah pratinjau yang perlu diperiksa. Tidak ada perubahan pada script atau publikasi sebelum Anda menerapkannya.</p>':''}${action?'<label class="radar-prompt" for="radarCustomPrompt">Prompt khusus (opsional)<textarea id="radarCustomPrompt" maxlength="12000" rows="7" placeholder="Contoh: Buat script 8 menit, hook kontroversial, bahasa percakapan, alur PAS, tutup dengan pertanyaan reflektif.">'+esc(radarUi.prompts?.[action]||'')+'</textarea><span class="hint">Tentukan topik, durasi, gaya dan struktur. Bisa membuat script baru meskipun kolom script masih kosong. Prompt disimpan selama sesi ini.</span></label><button class="btn primary" id="radarGenerateAI">Buat pratinjau</button>':''}<div id="radarAIResult"></div>`);
  rDialog.onclick=null;radarAIBind(config);
  if(!action)return;
  $('#radarCustomPrompt').oninput=e=>{(radarUi.prompts||={})[action]=e.target.value;};
  $('#radarGenerateAI').onclick=()=>radarRun(async()=>{
    const btn=$('#radarGenerateAI'),select=$('#radarAIModel'),check=$('#radarCheckAI'),provider=$('#radarAIProvider');if(!select)return;
    btn.disabled=true;if($('#radarTestAI'))$('#radarTestAI').disabled=true;select.disabled=true;check.disabled=true;if(provider)provider.disabled=true;btn.textContent='Membuat pratinjau…';
    const model=select.value,customPrompt=$('#radarCustomPrompt').value;$('#radarModalError').classList.add('hide');
    try{const result=await rPost('ai',{action,...context,customPrompt,model,provider:provider?.value||radarUi.data.ai.providerId});radarUi.aiLast={result,action,context,edit,epoch};if(btn.isConnected)radarAIResult(result,action,context,edit,epoch);}
    finally{const fresh=await api(radarAIPath()).catch(()=>null),next=fresh?.ai||radarUi.data.ai;radarUi.data.ai=next;if(btn.isConnected){$('#radarAIControls').innerHTML=radarAIControls(next);radarAIBind(next);}radarList();}
  });
}
document.getElementById('scriptAI').onclick=()=>radarRun(async()=>{if(!hub.editing)return;radarModal('Bantuan AI untuk script',`<p class="hint">Pilih bantuan. Script dan sumber riset yang tersedia akan dipakai sebagai bahan.</p>${radarUi.aiLast?'<button class="btn" id="radarPreviousAI">Buka hasil AI terakhir</button>':''}<div class="radar-issue-actions"><button class="btn" data-ai-action="script">Buat / perbaiki script · prompt custom</button><button class="btn" data-ai-action="shorts">Long → 3 Short</button><button class="btn" data-ai-action="storyboard">Storyboard</button></div>`);if($('#radarPreviousAI'))$('#radarPreviousAI').onclick=()=>{const last=radarUi.aiLast;radarModal('Hasil AI terakhir','<div id="radarAIResult"></div>');rDialog.onclick=null;radarAIResult(last.result,last.action,last.context,last.edit,last.epoch);};rDialog.onclick=e=>{const b=e.target.closest('[data-ai-action],[data-r-close]');if(!b)return;if(b.hasAttribute('data-r-close'))return rDialog.close();radarRun(()=>radarAI(b.dataset.aiAction,{script:formValue('script').value,title:formValue('title').value,brief:formValue('brief').value.slice(0,4000),contentId:hub.editing.isNew?null:hub.editing.content.id,sources:readForm().sources}));};});

function radarAIResult(result,action,context,edit,epoch){const box=$('#radarAIResult');box.innerHTML=`${result.fallbackHistory?.length?'<p class="notice">Pindah otomatis: '+result.fallbackHistory.map(h=>esc(h.provider)+' ('+esc(h.reason)+')').join(' → ')+' → '+esc(result.provider)+'.</p>':''}<p class="hint">Pratinjau · ${esc([result.provider,result.model].filter(Boolean).join(' · '))}</p><div class="radar-ai-text radar-prose">${HubScriptFormat.render(result.text)}</div><details class="radar-source-text"><summary>Lihat teks asli</summary><pre>${esc(result.text)}</pre></details>${result.sources.length?'<h3>Rujukan yang tersedia</h3>'+result.sources.map(s=>`<p>[${s.number}] ${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:esc(s.title)}</p>`).join(''):''}${action==='script'||action==='storyboard'?'<button class="btn primary" id="radarApplyAI">'+(action==='script'?'Terapkan ke script':'Terapkan ke rencana produksi')+'</button>':''}${action==='summary'?'<button class="btn primary" id="radarAIToDraft">Buat draft dari angle</button>':''}${result.drafts.map((d,n)=>`<article class="hub-panel"><h3>${esc(d.title)}</h3><p>${esc(d.angle)}</p><div class="radar-ai-text radar-prose">${HubScriptFormat.render(d.script)}</div><button class="btn" data-r-ai-draft="${n}">Buka draft Short ${n+1}</button></article>`).join('')}`;if($('#radarApplyAI'))$('#radarApplyAI').onclick=()=>{if(!edit||hub.editing!==edit||edit.epoch!==epoch)return toast('Script berubah selama AI bekerja. Tutup pratinjau dan ulangi dengan versi terbaru.');const key=action==='script'?'script':'productionNotes';HubRichText.setFormatted(formValue(key),HubScriptFormat.render(result.text));markDirty();rDialog.close();toast('Hasil AI diterapkan. Periksa teks sebelum produksi.');};if($('#radarAIToDraft'))$('#radarAIToDraft').onclick=()=>radarDraft(radarUi.data.issues.find(i=>i.id===context.issueId),{angle:result.text.slice(0,4000)});box.querySelectorAll('[data-r-ai-draft]').forEach(b=>b.onclick=()=>radarRun(async()=>{const d=result.drafts[Number(b.dataset.rAiDraft)];const sources=context.sources||edit?.content.sources||[];rDialog.close();navigate('library');await newContent({title:d.title,script:d.script,brief:d.angle,format:'shorts',sources:structuredClone(sources)});}));}
